import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Container, Header, Statistic, Segment, Grid } from 'semantic-ui-react';

import { loadPainel } from '../../actions/transporte';

const PainelGeral = () => {
  const dispatch = useDispatch();
  const painel = useSelector((state) => state.transporte?.painel);

  useEffect(() => {
    dispatch(loadPainel());
  }, [dispatch]);

  const dados = painel?.data || {};
  const situacoes = dados.viagens_por_situacao || {};

  return (
    <Container style={{ marginTop: '2em' }}>
      <Header as="h2">Painel Geral de Controle</Header>
      <Grid columns={3} padded>
        <Grid.Row>
          <Grid.Column>
            <Segment color="teal" inverted center aligned>
              <Statistic
                inverted
                label="Viagens programadas"
                value={situacoes.programada ?? 0}
              />
            </Segment>
          </Grid.Column>
          <Grid.Column>
            <Segment color="yellow" inverted center aligned>
              <Statistic
                inverted
                label="Viagens em andamento"
                value={situacoes.em_andamento ?? 0}
              />
            </Segment>
          </Grid.Column>
          <Grid.Column>
            <Segment color="green" inverted center aligned>
              <Statistic
                inverted
                label="Veículos disponíveis"
                value={dados.veiculos_disponiveis ?? 0}
              />
            </Segment>
          </Grid.Column>
        </Grid.Row>
      </Grid>
    </Container>
  );
};

export default PainelGeral;
